#!/usr/bin/env python3
"""Bounded source contract checks, NOT Swift/native/device execution."""
from pathlib import Path
import sys, os
root=Path(os.environ['BLIND_SOURCE_ROOT']) if 'BLIND_SOURCE_ROOT' in os.environ else (Path(sys.argv[1]) if len(sys.argv)>1 else Path(__file__).resolve().parents[2])
def read(p): return (root/p).read_text()
core=read('ios/BlindAssist/MeshCandidateDiagnostics.swift')
nav=read('ios/BlindAssist/NavigationModel.swift')
view=read('ios/BlindAssist/DashboardView.swift')
scene=read('ios/BlindAssist/ObservedSceneRuntime.swift')
tests=read('ios/BlindAssistTests/NormalOwnerMeshConnectionTests.swift')
checks=[]
def check(name,yes):
    if not yes:raise AssertionError(name)
    checks.append(name)
check('explicit diagnostic-only compile gate',core.startswith('#if DEBUG && BLIND_MESH_CANDIDATE_DIAGNOSTICS\n'))
check('reuse strict classified83 owner',all(s in core for s in ['MeshCandidateIngress83(maxAnchors:Self.maxAnchors,maxCopies:1','.classifiedFloorOnly','.requireSuppliedXZOverPolygon','.latestValidatedAnchorRevision']))
check('exact existing native anchor decoder', 'owner?.ingest(selected,receiptUptime:clock(),limits:limits)' in core)
check('no sampled adapter used as full geometry','NativeClassifiedHitEvidence' not in core and 'NativeObservationRecord' not in core and '.prefix(' not in core)
check('whole anchor and aggregate ceilings', all(s in core for s in ['maxAnchors = 32','maxVertices = 30_000','maxTriangles = 30_000','proposed.values.reduce','Anchor/tombstone budget exceeded']))
check('bounded frame inventory', 'frame.anchors.count <= 128' in core)
check('missing observations stay unresolved',all(s in core for s in ['present.subtracting(ids).subtracting(missing)','newIDs.union(appeared).union(vanished).union(resized)','missing.formUnion(vanished)','dirty.isEmpty,missing.isEmpty']))
check('actual removal distinct','owner?.remove(anchorID:anchorID,receiptUptime:receiptUptime)' in core)
check('one rotating whole copy',all(s in core for s in ['candidates[cursor % candidates.count]','dirty.remove(selected.identifier)']))
check('invalid replacements retire before event admission','retire() // Even malformed/omitted/newer replacement' in core)
check('same-session monotonic frame admission','latestFrame!.session == frame.session && frame.capturedAt > latestFrame!.capturedAt' in core)
check('fresh0.5s admission and dated8s history','clock()-value.sceneCapturedAt <= 0.5' in core and 'clock()-value.frame.capturedAt <= 8' in core)
check('actual planner endpoints feed native','owner.request(start:value.start,goal:value.goal,body:body,expectedSource:source)' in core)
check('postquery exact original source',all(s in core for s in ['source.geometry.revision == candidate.route.revision','Set(source.geometry.anchors.map(\\.anchorID)) == Set(present.map(\\.uuidString))']))
check('reuse actual collision kernel', 'SeatedMeshRouteAudit.run(source:source.geometry,route:candidate.route' in core)
check('raw body and separate margin','radius:value.radius,height:value.height,margin:value.margin' in core and 'MeshCandidateBody(radius:value.radius,height:value.height)' in core)
check('scoped raw work clearing before finish','work.clear() // Scope containing source/native-route locals returned before clearing.' in core)
check('real native plus operation drain','guard nativeDrained,!pending,let callback=drain' in core and 'DispatchQueue.main.async { [self] in finishDrain() }' in core)
check('UI reads pure', 'meshCandidateDiagnostics.displayStatus' in nav and 'meshCandidateDiagnostics.displayPoints' in nav)
check('normal urgent processing precedes meshcopy',nav.index('processDepthHazards(observation, frame: frame, receivedAt: receivedAt)') < nav.index('meshCandidateDiagnostics.observe(frame: frame'))
check('no camera takeover', 'ARSession(' not in core and '.delegate' not in core)
check('goal namespaces separate','plan.goalRevision == companionWorkingState.goalRevision' not in nav and 'self.companionWorkingState.goalRevision == goalRevision' in nav and 'diagnosticIntentIsCurrent(session: sessionID, revision: plan.goalRevision)' in nav)
check('original local intent namespace check','self.session == session && goalRevision == revision' in scene)
check('body and mount revision rechecked','current.profileRevision == profile.profileRevision, current.mountRevision == profile.mountRevision' in nav and 'current.envelope == body' in nav)
check('explicit developer control displayed','Check frozen look-ahead candidate against admitted mesh' in view)
check('not original polyline or wearer connector','not its original intermediate polyline or wearer connector' in core)
check('five exact authored native cases',tests.count('func test') == 5)
check('real owned buffers not forgedvalidatedsource', '.owned(.init(context:context,anchorID:id,plan:plan' in tests and 'MeshSnapshot82.preflight' in tests and 'SourceSnapshot(' not in tests)
check('mixed roles retained from same actual anchor', 'classificationBytes:roles' in tests and '$0.role == .floor' in tests and '$0.role == .obstacle' in tests)
check('held real oracle and real native discard before release',tests.index('cleanup.start() // Terminal discard while real oracle progress is held.') < tests.index('holding=false;release.resume()') and 'owner.nativeDiscardAcknowledgedForTesting' in tests)
check('successive owners await real drain','guard await awaitDrain(cleanup) else{return} // Before allocating the next native owner.' in tests)
check('standalone cleanup sole wait','XCTestExpectation(description:"native and operation drain")' in tests and tests.count('fulfillment(of:[drained]') == 1)
check('no normal physicaloutput sink',not any(x in core for x in ['FeedbackManager','SpatialLocalizationCapture(','.speak(','.beacon(']))
check('explicit receipt age not capture age','Oldest retained anchor receipt age' in core and 'not sensor capture age' in core and 'remembered ARFrame anchor does not refresh geometry' in core)
check('bounded32 actual source sequence','let ids=(0..<32)' in tests and 'owner.requestSourceForTesting' in tests and 'XCTAssertGreaterThan(time.now - (try XCTUnwrap(oldest)),1.9)' in tests)
check('timestamp unavailability preserved','snapshot.geometry.records.allSatisfy {$0.captureUptime == nil}' in tests)
check('same-ID tombstone reappearance needs real recopy','let appeared=ids.subtracting(present)' in core and 'real restored source after same-ID removal' in tests)
check('camera handoff requires actual ownership release','return owner == nil && !pending && drain == nil' in core and nav.index('guard meshCandidateDiagnostics.canYieldCamera else') < nav.index('seatedDiagnosticHold = true // Before cleanup'))
check('RoomPlan release guard precedes transfer',nav.index('guard meshCandidateDiagnostics.canYieldCamera else',nav.index('func scanPlace(')) < nav.index('places.startScan(',nav.index('func scanPlace(')))
check('held native ACK cannot yield camera','XCTAssertFalse(owner.canYieldCamera,"Disabled/stopped is not an exclusive-camera handoff permission")' in tests)
check('visible seated-only latency warning','Seated developer test only. Full-buffer copying and synchronous collision checks may delay camera alerts.' in view)
print(f'{len(checks)} source contracts passed; native fixtures UNRUN')
